"""Bring site/skills.json in line with what is live on GitHub, without a human merge.

    python tools/agent-skills/sync.py            # report what would change
    python tools/agent-skills/sync.py --write    # apply it, then regenerate the hub and pages

Ground truth is every public, non-fork arm-pz repo that ships one SKILL.md and passes the shape
test. For each manifest entry and each such repo, sync decides one of:

  add       an eligible repo with no entry gets a generated page
  refresh   a generated page whose repo HEAD moved is re-measured; hand-written copy is kept
  quality   any page whose repo HEAD moved gets its quality record (version, date, limits) re-read
  rename    the repo answers under a new name; the entry, its page folder and the workflows follow,
            and the old name becomes an alias that _redirects sends to the new page
  remove    the repo is gone or private (the API says Not Found); the entry and a generated page go
  hold      something needs a person: an empty About, a failed shape test, a bespoke page whose
            copy may still use the old name. Reported, never guessed at.

Bespoke pages are moved on a rename but never edited. Denied repos never publish.
"""

import argparse
import json
import shutil
import subprocess
import sys
from pathlib import Path

import discover
import gen_home
import gen_page
import skilllib

OWNER = discover.OWNER


def gh_json(*args):
    out = subprocess.run([discover.GH, *args], capture_output=True, text=True)
    if out.returncode != 0:
        return None, out.stderr.strip()
    try:
        return json.loads(out.stdout), None
    except json.JSONDecodeError as err:
        # Every caller branches on data is None; a zero-exit non-JSON body must not
        # escape as a traceback and skip resolve()'s "unreadable is never gone" rule.
        return None, f"gh {' '.join(args)} returned unreadable JSON: {err}"


def live_repos():
    data, err = gh_json("repo", "list", OWNER, "--limit", "1000", "--json",
                        "name,isFork,visibility,isArchived,description")
    if data is None:
        raise SystemExit(f"cannot list {OWNER} repos: {err}")
    return {r["name"]: r for r in data if r["visibility"].lower() == "public" and not r["isFork"]}


def resolve(repo):
    """('same'|'renamed'|'gone', current full name). Unreadable is an error, never 'gone'."""
    data, err = gh_json("api", f"repos/{repo}")
    if data is None:
        if "Not Found" in err or "HTTP 404" in err:
            return "gone", None
        raise SystemExit(f"cannot read {repo}: {err}")
    if data.get("private"):
        return "gone", None
    full = data["full_name"]
    return ("same" if full.lower() == repo.lower() else "renamed"), full


def has_skill_md(name):
    """Cheap pre-check from the git tree, so non-skill repos are never downloaded."""
    data, err = gh_json("api", f"repos/{OWNER}/{name}/git/trees/HEAD?recursive=1")
    if data is None:
        if "Git Repository is empty" in err or "Not Found" in err:
            return False
        raise SystemExit(f"cannot read the tree of {OWNER}/{name}: {err}")
    return any(i["path"] == "SKILL.md" or i["path"].endswith("/SKILL.md") for i in data.get("tree", []))


def head(repo):
    """(sha, YYYY-MM-DD commit date) of the repo's default-branch HEAD."""
    data, err = gh_json("api", f"repos/{repo}/commits/HEAD")
    if data is None:
        raise SystemExit(f"cannot read HEAD of {repo}: {err}")
    date = ((data.get("commit") or {}).get("committer") or {}).get("date") or ""
    return data["sha"], date[:10]


def locate(name, files):
    sk = next((p for p in (f"{name}/SKILL.md", "SKILL.md", f"skills/{name}/SKILL.md") if p in files), None)
    if sk is None:
        found = [p for p in files if p.endswith("/SKILL.md")]
        sk = found[0] if len(found) == 1 else None
    if sk is None:
        return None
    return "." if sk == "SKILL.md" else sk[: -len("/SKILL.md")]


def drop_from_workflows(manifest, name):
    for flow in manifest.get("workflows", []):
        for step in flow["steps"]:
            step["skills"] = [n for n in step["skills"] if n != name]
        flow["steps"] = [s for s in flow["steps"] if s["skills"]]
    manifest["workflows"] = [f for f in manifest.get("workflows", []) if f["steps"]]


def rename_in_workflows(manifest, old, new):
    for flow in manifest.get("workflows", []):
        for step in flow["steps"]:
            step["skills"] = [new if n == old else n for n in step["skills"]]


def plan(root, manifest, deny):
    repos = live_repos()
    denied = {d["repo"] for d in deny}
    actions = []
    known = set()
    heads = {}
    for entry in manifest["skills"]:
        repo = entry.get("repo")
        if repo is None:
            known.add(entry["name"])  # a pinned legacy archive owns its name
            continue
        short = repo.split("/", 1)[1]
        known.add(short)
        if short not in repos:
            state, full = resolve(repo)
            if state == "gone":
                actions.append(("remove", entry["name"], f"{repo} is gone or private"))
                continue
            if state == "renamed":
                known.add(full.split("/", 1)[1])
                # The site publishes OWNER's repos only (skilllib.validate_manifest).
                # A move to another account is the owner's call, so hold the entry
                # as it is instead of failing the whole sync on it.
                if full.split("/", 1)[0].lower() != OWNER.lower():
                    actions.append(("hold", entry["name"], f"moved to {full}, outside {OWNER}; "
                                    "the entry is kept as it was until the site decides to list it"))
                    continue
                actions.append(("rename", entry["name"], full))
                continue
        if repo not in heads:
            heads[repo] = head(repo)
        sha, date = heads[repo]
        if entry["page"] == "generated" and sha != entry["pageSource"]["commit"]:
            actions.append(("refresh", entry["name"], sha))
        if entry["page"] != "none" and sha[:7] != (entry.get("quality") or {}).get("commit"):
            actions.append(("quality", entry["name"], (sha, date)))
    for name, r in sorted(repos.items()):
        if name in known or f"{OWNER}/{name}" in denied:
            continue
        if not has_skill_md(name):
            continue
        files = discover.fetch_files(name)
        fails = skilllib.shape_failures(name, files, denied=frozenset(denied), is_fork=r["isFork"])
        if fails:
            if any(p.endswith("SKILL.md") for p in files):
                actions.append(("hold", name, "; ".join(fails)))
            continue
        if not (r.get("description") or "").strip():
            actions.append(("hold", name, "repository About is empty; the build needs it"))
            continue
        actions.append(("add", name, files))
    return actions


def apply(root, manifest, actions):
    by_name = {s["name"]: s for s in manifest["skills"]}
    notes = []
    fetched = {}

    def files_of(short):
        if short not in fetched:
            fetched[short] = discover.fetch_files(short)
        return fetched[short]

    for kind, name, detail in actions:
        if kind == "remove":
            entry = by_name.pop(name)
            drop_from_workflows(manifest, name)
            if entry["page"] == "generated" and (root / name).is_dir():
                shutil.rmtree(root / name)
            elif entry["page"] == "bespoke":
                notes.append(f"{name}: bespoke page folder kept in git but no longer published")
        elif kind == "rename":
            entry = by_name.pop(name)
            new_repo = detail.split("/", 1)[1]
            files = discover.fetch_files(new_repo)
            path = locate(new_repo, files)
            if path is None:
                by_name[name] = entry
                notes.append(f"{name}: renamed to {detail} but its SKILL.md could not be located; held")
                continue
            # Keep the old entry name when the skill folder inside the repo kept it.
            new_name = name if path.endswith(f"skills/{name}") or path == name else new_repo
            entry["repo"] = detail
            entry["path"] = path
            if entry.get("install"):
                entry["install"] = entry["install"].replace(f"{OWNER}/{name}", detail)
            if new_name != name:
                entry["name"] = new_name
                entry["aliases"] = sorted(set(entry.get("aliases", [])) | {name})
                rename_in_workflows(manifest, name, new_name)
                if (root / name).is_dir() and not (root / new_name).exists():
                    (root / name).rename(root / new_name)
                if entry["page"] == "bespoke":
                    notes.append(f"{new_name}: bespoke page moved from /{name}/; its copy may still say '{name}'")
            if entry["page"] == "generated":
                try:
                    entry["pageSource"], _ = discover.measure(new_repo, files, path)
                except skilllib.ManifestError as err:
                    notes.append(f"{entry['name']}: renamed, but {err}; page not re-measured")
            by_name[entry["name"]] = entry
        elif kind == "refresh":
            entry = by_name[name]
            short = entry["repo"].split("/", 1)[1]
            files = files_of(short)
            path = (locate(name, files) if short == name else None) or entry["path"]
            if discover.entry_point(files, path) is None:
                notes.append(f"{name}: no SKILL.md or plugin.json at {path} any more; page not refreshed")
                continue
            try:
                source, _ = discover.measure(short, files, path)
            except skilllib.ManifestError as err:
                notes.append(f"{name}: {err}; page not refreshed")
                continue
            entry["path"] = path
            entry["pageSource"] = source
            entry["stats"] = discover.stats_line(source)
        elif kind == "quality":
            entry = by_name[name]
            sha, date = detail
            files = files_of(entry["repo"].split("/", 1)[1])
            entry["quality"] = discover.quality(files, entry["path"], sha, date)
        elif kind == "add":
            files = detail
            path = locate(name, files)
            try:
                source, _ = discover.measure(name, files, path)
            except skilllib.ManifestError as err:
                notes.append(f"{name}: {err}; not added")
                continue
            group = discover.assign_group(name, source["description"])
            tag = discover.assign_tag(group, name, source["description"])
            order = max([s["order"] for s in by_name.values()] + [0]) + 1
            by_name[name] = discover.candidate_entry(name, path, group, tag, source, order)
        elif kind == "hold":
            notes.append(f"{name}: held, {detail}")
    manifest["skills"] = sorted(by_name.values(), key=lambda s: s["order"])
    skilllib.validate_manifest(manifest)
    return notes


def main(argv=None):
    parser = argparse.ArgumentParser()
    parser.add_argument("--root", default=".")
    parser.add_argument("--write", action="store_true")
    parser.add_argument("--summary", help="append a markdown summary to this file")
    args = parser.parse_args(argv)
    root = Path(args.root).resolve()
    manifest = skilllib.load_manifest(root)
    skilllib.validate_manifest(manifest)
    actions = plan(root, manifest, skilllib.load_deny(root))

    lines = [f"{kind:<8} {name:<34} {detail if isinstance(detail, str) else ''}".rstrip()
             for kind, name, detail in actions]
    print("\n".join(lines) or "in sync: nothing to change")
    notes = []
    if args.write and any(kind != "hold" for kind, _, _ in actions):
        notes = apply(root, manifest, actions)
        with open(root / "site" / "skills.json", "w", encoding="utf-8", newline="\n") as fh:
            json.dump(manifest, fh, indent=2, ensure_ascii=False)
            fh.write("\n")
        gen_page.main(["--write", "--root", str(root)])
        gen_home.main(["--write", "--root", str(root)])
    elif args.write:
        notes = [f"{name}: held, {detail}" for kind, name, detail in actions if kind == "hold"]
    for note in notes:
        print(f"NOTE {note}")
    if args.summary:
        with open(args.summary, "a", encoding="utf-8") as fh:
            fh.write("## sync\n\n" + ("\n".join(f"- `{l}`" for l in lines) or "- in sync") + "\n")
            fh.writelines(f"- note: {n}\n" for n in notes)
    return 0


if __name__ == "__main__":
    sys.exit(main())
        if tokens & set(keywords) or any(k in text for k in keywords if "-" in k):
            return group
    return "skill-authoring"


def assign_tag(group, name, description):
    tokens = words(name, topic_text(description))
    if group in ("career", "outbound"):
        return group
    if group == "seo-search":
        return "seo"
    if group == "publish-discover":
        return "discovery" if tokens & {"discover", "findable", "listing"} else "publishing"
    if group == "writing-growth":
        return "editorial" if tokens & {"edit", "proofread", "wordsmith"} else "content"
    if group == "thinking-learning":
        if tokens & {"decisions", "decision", "strategy"}:
            return "decisions"
        if "arena" in tokens:
            return "arena"
        if tokens & {"research", "data", "sources"}:
            return "research"
        return "learning"
    if group == "ship-checks":
        if "performance" in tokens:
            return "performance"
        return "build" if tokens & {"code", "website", "prompt"} else "release"
    return "authoring"


def draft_blurb(description):
    text = " ".join(description.split())
    match = re.match(r"(.+?[.!?])(?:\s|$)", text)
    sentence = match.group(1) if match else text
    if len(sentence) > 240:
        sentence = sentence[:240].rsplit(" ", 1)[0].rstrip(" ,;:-") + "…"
    return sentence


def gh(*args, check=True):
    result = subprocess.run([GH, *args], capture_output=True, text=True)
    if check and result.returncode != 0:
        raise SystemExit(f"gh {' '.join(args)} failed: {result.stderr.strip()}")
    return result.stdout


def list_repos():
    data = json.loads(gh("repo", "list", OWNER, "--limit", "1000",
                         "--json", "name,isFork,visibility"))
    return [r for r in data if r["visibility"].lower() == "public"]


def proposal_open():
    out = gh("pr", "list", "--state", "open", "--json", "headRefName",
             "--jq", ".[].headRefName")
    return any(line.startswith("proposal/") for line in out.split())


def fetch_files(repo):
    return skilllib.expand_tarball(gh_bytes(["api", f"repos/{OWNER}/{repo}/tarball"]))


def gh_bytes(args):
    result = subprocess.run([GH, *args], capture_output=True)
    if result.returncode != 0:
        raise SystemExit(f"gh {' '.join(args)} failed: "
                         f"{result.stderr.decode('utf-8', 'replace').strip()}")
    return result.stdout


def entry_point(files, path):
    """The file that describes what lives at path: a SKILL.md, or a mod's plugin.json."""
    prefix = "" if path == "." else path + "/"
    for rel in ("SKILL.md", ".claude-plugin/plugin.json"):
        if prefix + rel in files:
            return prefix + rel
    return None


def measure(repo, files, path):
    point = entry_point(files, path)
    if point is None:
        raise KeyError(f"no SKILL.md or .claude-plugin/plugin.json at {path}")
    text = files[point].decode("utf-8", "replace")
    if point.endswith("SKILL.md"):
        description = skilllib.parse_frontmatter(text).get("description")
    else:
        description = json.loads(text).get("description")
    if not (description or "").strip():
        raise skilllib.ManifestError(f"{point} has no description")
    selected = skilllib.select_skill_files(files, path)
    blob = skilllib.pack(selected)
    commit = json.loads(gh("api", f"repos/{OWNER}/{repo}/commits/HEAD"))["sha"]
    license_id = gen_page.detect_license(
        files.get("LICENSE", b"").decode("utf-8", "replace"))
    return {
        "description": " ".join(description.split()),
        "files": [{"path": name,
                   "lines": data.count(b"\n"),
                   "bytes": len(data)}
                  for name, data in sorted(selected.items())],
        "fileCount": len(selected),
        "lines": sum(data.count(b"\n") for data in selected.values()),
        "bytes": len(blob),
        "license": license_id,
        "commit": commit,
        "sha256": skilllib.sha256_hex(blob),
    }, blob


def quality(files, path, sha, date):
    """What a page's quality block shows, read from the files at one commit."""
    point = entry_point(files, path)
    text = files[point].decode("utf-8", "replace") if point else ""
    if point and point.endswith("plugin.json"):
        data = json.loads(text)
        version, description = data.get("version"), data.get("description", "")
    else:
        version = skilllib.frontmatter_version(text)
        description = skilllib.parse_frontmatter(text).get("description", "") if text else ""
    _, _, _, nots = gen_page.split_description(description)
    return {"version": str(version) if version else None, "commit": sha[:7],
            "updated": date, "notFor": nots}


def stats_line(source):
    count = source["fileCount"]
    return (f'{count} file{"" if count == 1 else "s"} · {source["lines"]:,} lines · '
            f'{max(1, round(source["bytes"] / 1024))} KB')


def candidate_entry(name, path, group, tag, source, order):
    title = skilllib.title_case(name)
    return {
        "name": name,
        "repo": f"{OWNER}/{name}",
        "path": path,
        "group": group,
        "tag": tag,
        "title": title,
        "pageTitle": skilllib.skill_page_title(title),
        "blurb": draft_blurb(source["description"]),
        "stats": stats_line(source),
        "install": f"npx skills add {OWNER}/{name}",
        "page": "generated",
        "order": order,
        "pageSource": source,
    }


def bash_command():
    # Windows resolves bare "bash" to the WSL stub, which fails in a subprocess.
    if os.name == "nt":
        candidate = Path(os.environ.get("ProgramFiles", r"C:\Program Files")) / "Git" / "bin" / "bash.exe"
        if candidate.is_file():
            return str(candidate)
    return "bash"


def run_gate(root):
    env = dict(os.environ, GH=GH)
    for cmd in (
        [sys.executable, "-m", "unittest", "discover",
         "-s", "tools/agent-skills/tests", "-v"],
        [sys.executable, "tools/agent-skills/build.py"],
        [sys.executable, "tools/agent-skills/gen_home.py", "--check"],
        [sys.executable, "tools/agent-skills/gen_page.py", "--check"],
        [sys.executable, "tools/agent-skills/gen_sitemap.py", "--write"],
        [bash_command(), "tools/agent-skills/make_dist.sh"],
        [sys.executable, "tools/agent-skills/check_dist.py"],
        ["node", "tools/agent-skills/verify.mjs", "local"],
    ):
        subprocess.run(cmd, cwd=root, check=True, env=env)


def main(argv=None):
    parser = argparse.ArgumentParser()
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--report", action="store_true")
    mode.add_argument("--propose", action="store_true")
    parser.add_argument("--root", default=".")
    parser.add_argument("--only", metavar="NAMES",
                        help="propose only these comma-separated repos; the report lists all")
    parser.add_argument("--dry-run", action="store_true",
                        help="propose: write files locally, do not commit, push or open a PR")
    args = parser.parse_args(argv)
    root = Path(args.root).resolve()
    manifest = skilllib.load_manifest(root)
    deny = skilllib.load_deny(root)
    denied = {item["repo"] for item in deny}
    existing = {s["name"] for s in manifest["skills"]}
    only = ({n.strip() for n in args.only.split(",") if n.strip()}
            if args.only else None)

    repos = list_repos()
    report = []
    eligible = []
    seen = set()
    for repo in sorted(repos, key=lambda r: r["name"]):
        name = repo["name"]
        seen.add(name)
        if only is not None and name not in only:
            report.append((name, "skip", "not selected by --only"))
            continue
        if name in existing or repo["isFork"] or f"{OWNER}/{name}" in denied:
            report.append((name, "skip", "already published, fork, or denied"))
            continue
        try:
            files = fetch_files(name)
        except SystemExit as err:
            report.append((name, "error", str(err)))
            continue
        fails = skilllib.shape_failures(name, files,
                                        denied=denied, is_fork=repo["isFork"])
        report.append((name, "eligible" if not fails else "ineligible",
                       "; ".join(fails)))
        if not fails:
            eligible.append((name, files))

    if only is not None:
        missing = sorted(only - seen)
        if missing:
            raise SystemExit(f"--only names not found among public repos: {', '.join(missing)}")

    for name, status, reason in report:
        print(f"{name:<40} {status:<10} {reason}")
    if args.report:
        return 0

    if proposal_open():
        print("proposal already open; nothing to do")
        return 0
    if not eligible:
        print("no eligible repos")
        return 0
    if not args.dry_run and subprocess.run(
            ["git", "status", "--porcelain"], cwd=root, capture_output=True,
            text=True).stdout.strip():
        raise SystemExit("working tree is dirty; discovery must run from a clean checkout")

    deferred = []
    for name, files in eligible:
        try:
            sk = next(p for p in (f"{name}/SKILL.md", "SKILL.md", f"skills/{name}/SKILL.md")
                      if p in files)
            layout = "." if sk == "SKILL.md" else (
                "skills/" + name if sk.startswith("skills/") else name)
            source, _ = measure(name, files, layout)
            group = assign_group(name, source["description"])
            tag = assign_tag(group, name, source["description"])
            deferred.append((name, layout, group, tag, source))
        except (SystemExit, skilllib.ManifestError) as err:
            print(f"DROPPED {name}: {err}", file=sys.stderr)

    if not deferred:
        print("no candidate survived measurement")
        return 1

    order = max(s["order"] for s in manifest["skills"])
    entries = []
    for name, layout, group, tag, source in deferred:
        order += 1
        entries.append(candidate_entry(name, layout, group, tag, source, order))
    manifest["skills"].extend(entries)
    skilllib.validate_manifest(manifest)
    with open(root / "site" / "skills.json", "w", encoding="utf-8", newline="\n") as fh:
        json.dump(manifest, fh, indent=2, ensure_ascii=False)
        fh.write("\n")
    written = gen_page.write_pages(root, manifest)
    subprocess.run([sys.executable, str(root / "tools/agent-skills/gen_home.py"),
                    "--write", "--root", str(root)], check=True)
    run_gate(root)

    if args.dry_run:
        print(f"dry run: {len(written)} pages written, manifest updated, nothing committed")
        return 0

    branch = f"proposal/{dt.date.today().isoformat()}"
    names = [e["name"] for e in entries]
    subprocess.run(["git", "switch", "-c", branch], cwd=root, check=True)
    paths = ["site/skills.json", *gen_home.HUB_PAGES, *written,
             *(f"workflows/{f['slug']}/index.html" for f in manifest.get("workflows", []))]
    subprocess.run(["git", "add", *paths], cwd=root, check=True)
    subprocess.run(["git", "commit", "-m",
                    f"propose {len(names)} skill(s): {', '.join(names)}"],
                   cwd=root, check=True)
    subprocess.run(["git", "push", "-u", "origin", branch], cwd=root, check=True)
    body = "\n\n".join(
        f"### {e['title']} (`{e['repo']}`)\n"
        f"- group/tag: `{e['group']}` / `{e['tag']}`\n"
        f"- install: `{e['install']}`\n"
        f"- digest: `sha256:{e['pageSource']['sha256']}`\n"
        f"- measured: {e['pageSource']['fileCount']} files, "
        f"{e['pageSource']['lines']} lines, {e['pageSource']['bytes']} bytes\n"
        f"- [ ] correct group/tag/copy if needed, then regenerate with "
        f"`gen_page.py --write && gen_home.py --write`"
        for e in entries)
    subprocess.run([GH, "pr", "create", "--title",
                    f"Propose {len(names)} new skill(s)", "--body",
                    "Discovery found eligible repos. Merging publishes them.\n\n" + body,
                    "--head", branch], cwd=root, check=True)
    return 0


if __name__ == "__main__":
    sys.exit(main())

